import Foundation

/// Translates Codex app-server notifications into `AgentEvent`s.
///
/// Written against the protocol generated by the real binary (`codex app-server generate-ts`) and
/// checked against recordings of it. Pure and synchronous, like its Claude counterpart.
///
/// Sub-agents stream on the same connection as the main thread, tagged with their own `threadId`.
/// Only the main thread may end a turn or change the session's state. Sub-agent work still flows
/// through here, because a sub-agent's edit approval needs the diff from its own `item/started`,
/// and it appears nested under an Agent row so nothing an agent does goes unseen.
struct CodexTranslator {
    /// What kind of server request is pending, which decides the shape of the reply.
    enum RequestKind: Sendable, Equatable {
        case command
        case fileChange
        case mcpApproval
        case form
        case link
        case userInput
    }

    let workingDirectory: String
    var rootThreadID: String?
    /// The policy the current turn runs under. Decides what an approval really means.
    var turnMode: ApprovalMode = .ask
    /// MCP servers the user configured. Others, such as bundled plugins, fail quietly.
    var userMCPServers: Set<String> = []

    private(set) var fileDiffs: [String: [DiffFile]] = [:]
    private(set) var filePaths: [String: [String]] = [:]
    private(set) var commands: [String: String] = [:]

    private var agentRows: [String: String] = [:]
    private var agentNames: [String: String] = [:]
    private var agentAnswers: [String: String] = [:]
    private var unclaimedSpawnRows: [String] = []
    private var openMessages: Set<String> = []
    private var shownError: String?

    init(workingDirectory: String) {
        self.workingDirectory = workingDirectory
    }

    private func isChild(_ params: JSONValue) -> Bool {
        guard let thread = params["threadId"]?.string, let rootThreadID else { return false }
        return thread != rootThreadID
    }

    mutating func translate(method: String, params: JSONValue) -> [AgentEvent] {
        let child = isChild(params)
        let thread = params["threadId"]?.string
        let parent = child ? thread.map { agentRow(for: $0).id } : nil

        switch method {
        case "item/agentMessage/delta":
            guard !child, let id = params["itemId"]?.string, let delta = params["delta"]?.string else { return [] }
            openMessages.insert(id)
            return [.textDelta(id: id, delta: delta, parentToolID: nil)]
        case "item/reasoning/summaryTextDelta":
            guard !child, let id = params["itemId"]?.string, let delta = params["delta"]?.string else { return [] }
            return [.thinkingDelta(id: id, delta: delta, parentToolID: nil)]
        case "item/commandExecution/outputDelta":
            guard let id = params["itemId"]?.string, let delta = params["delta"]?.string else { return [] }
            return [.toolOutput(id: id, delta: delta)]
        case "item/started":
            return params["item"].map { itemStarted($0, parent: parent) } ?? []
        case "item/completed":
            return params["item"].map { itemCompleted($0, parent: parent, thread: thread, isChild: child) } ?? []
        case "turn/started":
            shownError = child ? shownError : nil
            guard child, let thread else { return [] }
            let row = agentRow(for: thread)
            return row.isNew ? [.tool(agentCall(id: row.id, detail: "Sub-agent", parent: nil))] : []
        case "turn/completed":
            return child ? childTurnCompleted(params["turn"], thread: thread) : turnCompleted(params["turn"])
        case "turn/plan/updated":
            return child ? [] : [.todosUpdated((params["plan"]?.array ?? []).compactMap(Self.todoItem))]
        case "turn/diff/updated":
            return [.filesChanged]
        case "thread/tokenUsage/updated":
            guard !child, let usage = params["tokenUsage"], let limit = usage["modelContextWindow"]?.int,
                let used = usage["last"]?["totalTokens"]?.int
            else { return [] }
            return [.contextUsage(ContextUsage(usedTokens: used, maxTokens: limit))]
        case "account/rateLimits/updated":
            // Updates also arrive for other buckets, which must not replace the plan's own usage.
            guard let limits = params["rateLimits"], (limits["limitId"]?.string ?? "codex") == "codex" else { return [] }
            return Self.rateLimit(limits).map { [.rateLimit($0)] } ?? []
        case "error":
            return errorReported(params, isChild: child)
        case "warning":
            return params["message"]?.string.map { [.notice(Notice(level: .warning, text: $0, key: $0))] } ?? []
        case "configWarning":
            return params["summary"]?.string.map { [.notice(Notice(level: .info, text: $0, key: $0))] } ?? []
        case "deprecationNotice":
            return params["summary"]?.string.map { [.notice(Notice(level: .info, text: $0, key: $0))] } ?? []
        case "guardianWarning":
            return params["message"]?.string.map { [.notice(Notice(level: .info, text: $0, key: $0))] } ?? []
        case "model/rerouted":
            guard let from = params["fromModel"]?.string, let to = params["toModel"]?.string else { return [] }
            let text = "Codex switched this turn from \(from) to \(to)."
            return [.notice(Notice(level: .warning, text: text, key: text))]
        case "mcpServer/startupStatus/updated":
            guard params["status"]?.string == "failed", let name = params["name"]?.string,
                userMCPServers.contains(name)
            else { return [] }
            let text = "The MCP server \(name) didn't start, so its tools aren't available."
            return [.notice(Notice(level: .warning, text: text, key: "mcp-\(name)"))]
        default:
            return []
        }
    }

    // MARK: Items

    private mutating func itemStarted(_ item: JSONValue, parent: String?) -> [AgentEvent] {
        guard let id = item["id"]?.string else { return [] }
        switch item["type"]?.string {
        case "commandExecution":
            let command = Self.displayCommand(item["command"]?.string ?? "")
            commands[id] = command
            return [
                .tool(
                    ToolCall(
                        id: id, name: "shell", kind: .shell, title: "Run", detail: ToolDescriber.firstLine(command),
                        input: ["command": .string(command)], parentID: parent))
            ]
        case "fileChange":
            remember(fileChange: item, id: id)
            return [.tool(fileChangeCall(id: id, diffs: fileDiffs[id] ?? [], parent: parent))]
        case "mcpToolCall":
            return [
                .tool(
                    ToolCall(
                        id: id, name: "mcp", kind: .mcp, title: item["server"]?.string ?? "Tool",
                        detail: item["tool"]?.string ?? "", input: item["arguments"] ?? .object([:]), parentID: parent))
            ]
        case "webSearch":
            // The query only arrives when the item completes.
            return [.tool(ToolCall(id: id, name: "web_search", kind: .web, title: "Web search", detail: "", parentID: parent))]
        case "imageView":
            let path = ToolDescriber.relative(item["path"]?.string ?? "", to: workingDirectory)
            return [.tool(ToolCall(id: id, name: "view_image", kind: .read, title: "View image", detail: path, parentID: parent))]
        case "subAgentActivity":
            return subAgentActivity(item, parent: parent, isStartFrame: true)
        case "collabAgentToolCall":
            guard item["tool"]?.string == "spawnAgent" else { return [] }
            let row = "agent-\(id)"
            unclaimedSpawnRows.append(row)
            let prompt = ToolDescriber.firstLine(item["prompt"]?.string ?? "")
            return [.tool(agentCall(id: row, detail: prompt.isEmpty ? "Sub-agent" : prompt, parent: parent))]
        default:
            return []
        }
    }

    private mutating func itemCompleted(
        _ item: JSONValue, parent: String?, thread: String?, isChild: Bool
    ) -> [AgentEvent] {
        guard let id = item["id"]?.string else { return [] }
        switch item["type"]?.string {
        case "agentMessage":
            let text = item["text"]?.string ?? ""
            openMessages.remove(id)
            if isChild {
                if let thread { agentAnswers[thread] = text }
                return []
            }
            return [.textFinished(id: id, text: text, parentToolID: nil)]
        case "plan":
            return isChild ? [] : [.textFinished(id: id, text: item["text"]?.string ?? "", parentToolID: nil)]
        case "reasoning":
            let summary = (item["summary"]?.array ?? []).compactMap(\.string).joined(separator: "\n\n")
            return summary.isEmpty || isChild
                ? [] : [.thinkingFinished(id: id, text: summary, durationMs: nil, parentToolID: nil)]
        case "commandExecution":
            return [
                .toolFinished(
                    id: id, output: item["aggregatedOutput"]?.string ?? "", status: Self.status(item), diff: []),
                .filesChanged,
            ]
        case "fileChange":
            remember(fileChange: item, id: id)
            let diffs = fileDiffs[id] ?? []
            return [
                .tool(fileChangeCall(id: id, diffs: diffs, parent: parent)),
                .toolFinished(id: id, output: "", status: Self.status(item), diff: diffs),
                .filesChanged,
            ]
        case "mcpToolCall":
            let error = item["error"]?["message"]?.string
            let content = (item["result"]?["content"]?.array ?? []).compactMap { $0["text"]?.string }.joined(separator: "\n")
            return [.toolFinished(id: id, output: error ?? content, status: Self.status(item), diff: [])]
        case "webSearch":
            return webSearchCompleted(item, id: id, parent: parent)
        case "imageView":
            return [.toolFinished(id: id, output: "", status: .succeeded, diff: [])]
        case "subAgentActivity":
            return subAgentActivity(item, parent: parent, isStartFrame: false)
        case "collabAgentToolCall":
            return collabCompleted(item, id: id)
        case "contextCompaction":
            return isChild ? [] : [.notice(Notice(level: .info, text: "Conversation compacted to free up context"))]
        default:
            return []
        }
    }

    private mutating func remember(fileChange item: JSONValue, id: String) {
        let changes = item["changes"]?.array ?? []
        fileDiffs[id] = Self.diffs(changes, workingDirectory: workingDirectory)
        filePaths[id] = changes.flatMap { change -> [String] in
            [change["path"]?.string, change["kind"]?["move_path"]?.string].compactMap { $0 }
        }
    }

    private func fileChangeCall(id: String, diffs: [DiffFile], parent: String?) -> ToolCall {
        let detail = diffs.count == 1 ? (diffs.first.map(Self.displayPath) ?? "") : "\(diffs.count) files"
        return ToolCall(id: id, name: "apply_patch", kind: .edit, title: "Edit", detail: detail, diff: diffs, parentID: parent)
    }

    private static func displayPath(_ file: DiffFile) -> String {
        file.movedTo.map { "\(file.path) → \($0)" } ?? file.path
    }

    private func webSearchCompleted(_ item: JSONValue, id: String, parent: String?) -> [AgentEvent] {
        let action = item["action"]
        let queries = action?["queries"]?.array?.compactMap(\.string) ?? []
        let detail = queries.count > 1 ? queries.joined(separator: ", ") : (item["query"]?.string ?? "")
        let title: String =
            switch action?["type"]?.string {
            case "openPage", "open_page": "Open page"
            case "findInPage", "find_in_page": "Find in page"
            default: "Web search"
            }
        let results = (item["results"]?.array ?? []).compactMap { result -> String? in
            let parts = [result["title"]?.string, result["url"]?.string].compactMap { $0 }.filter { !$0.isEmpty }
            return parts.isEmpty ? nil : parts.joined(separator: " — ")
        }
        return [
            .tool(ToolCall(id: id, name: "web_search", kind: .web, title: title, detail: detail, parentID: parent)),
            .toolFinished(id: id, output: results.joined(separator: "\n"), status: .succeeded, diff: []),
        ]
    }

    // MARK: Sub-agents

    /// The transcript row for a sub-agent's thread, made on first sight if need be.
    private mutating func agentRow(for thread: String) -> (id: String, isNew: Bool) {
        if let id = agentRows[thread] { return (id, false) }
        if !unclaimedSpawnRows.isEmpty {
            let id = unclaimedSpawnRows.removeFirst()
            agentRows[thread] = id
            return (id, false)
        }
        let id = "agent-\(thread)"
        agentRows[thread] = id
        return (id, true)
    }

    private func agentCall(id: String, detail: String, parent: String?) -> ToolCall {
        ToolCall(id: id, name: "agent", kind: .subagent, title: "Agent", detail: detail, parentID: parent)
    }

    private mutating func subAgentActivity(_ item: JSONValue, parent: String?, isStartFrame: Bool) -> [AgentEvent] {
        guard let thread = item["agentThreadId"]?.string else { return [] }
        let name = Self.agentName(item["agentPath"]?.string)
        agentNames[thread] = name
        switch item["kind"]?.string {
        case "started":
            // The completed frame for `started` arrives at once, and must not end the row.
            guard isStartFrame else { return [] }
            if agentRows[thread] == nil { agentRows[thread] = "agent-\(thread)" }
            return [.tool(agentCall(id: agentRows[thread] ?? "agent-\(thread)", detail: name, parent: parent))]
        case "completed":
            return finishAgent(thread: thread, status: .succeeded)
        case "interrupted":
            return finishAgent(thread: thread, status: .cancelled)
        default:
            return []
        }
    }

    private mutating func collabCompleted(_ item: JSONValue, id: String) -> [AgentEvent] {
        guard item["tool"]?.string == "spawnAgent" else { return [] }
        let row = "agent-\(id)"
        guard let thread = item["receiverThreadIds"]?[0]?.string else {
            unclaimedSpawnRows.removeAll { $0 == row }
            return [.toolFinished(id: row, output: "", status: .failed, diff: [])]
        }
        if agentRows[thread] == nil {
            agentRows[thread] = row
            unclaimedSpawnRows.removeAll { $0 == row }
        }
        return []
    }

    private func finishAgent(thread: String, status: ToolStatus) -> [AgentEvent] {
        guard let row = agentRows[thread] else { return [] }
        return [.toolFinished(id: row, output: agentAnswers[thread] ?? "", status: status, diff: [])]
    }

    private func childTurnCompleted(_ turn: JSONValue?, thread: String?) -> [AgentEvent] {
        guard let thread else { return [] }
        let status: ToolStatus =
            switch turn?["status"]?.string {
            case "interrupted": .cancelled
            case "failed": .failed
            default: .succeeded
            }
        return finishAgent(thread: thread, status: status)
    }

    private static func agentName(_ path: String?) -> String {
        guard let path, !path.isEmpty else { return "Sub-agent" }
        return (path as NSString).lastPathComponent
    }

    // MARK: Turn ends and errors

    private mutating func turnCompleted(_ turn: JSONValue?) -> [AgentEvent] {
        let outcome: TurnSummary.Outcome =
            switch turn?["status"]?.string {
            case "interrupted": .interrupted
            case "failed": .failed
            default: .completed
            }
        let error = turn?["error"]
        var events: [AgentEvent] = []
        // A failure normally arrives as an `error` frame too. Show it once.
        if outcome == .failed, let error, !error.isNull, shownError != error["message"]?.string {
            events.append(.notice(Self.notice(for: error)))
        }
        shownError = nil
        events.append(
            .turnFinished(
                TurnSummary(outcome: outcome, durationMs: turn?["durationMs"]?.int, message: error?["message"]?.string)))
        return events
    }

    private mutating func errorReported(_ params: JSONValue, isChild: Bool) -> [AgentEvent] {
        guard let error = params["error"] else { return [] }
        if params["willRetry"]?.bool == true {
            guard !isChild else { return [] }
            // The retry starts the answer again, so drop what has streamed so far.
            let abandoned = openMessages
            openMessages.removeAll()
            var text = error["message"]?.string ?? "Reconnecting"
            if let details = error["additionalDetails"]?.string, !details.isEmpty { text += ": \(details)" }
            return abandoned.map { .itemRetracted(id: $0) } + [.notice(Notice(level: .warning, text: text, key: "retry"))]
        }
        if isChild {
            return [.notice(Notice(level: .warning, text: "A sub-agent stopped: \(error["message"]?.string ?? "unknown error")"))]
        }
        shownError = error["message"]?.string
        return [.notice(Self.notice(for: error))]
    }

    private static func notice(for error: JSONValue) -> Notice {
        if isAuthFailure(error) {
            return Notice(level: .error, text: "Codex isn't signed in. Sign in to continue.", action: .signIn)
        }
        return Notice(level: .error, text: error["message"]?.string ?? "Codex reported an error.")
    }

    static func isAuthFailure(_ error: JSONValue) -> Bool {
        guard let info = error["codexErrorInfo"] else { return false }
        if info.string == "unauthorized" { return true }
        return ["httpConnectionFailed", "responseStreamConnectionFailed", "responseStreamDisconnected"].contains {
            info[$0]?["httpStatusCode"]?.int == 401
        }
    }

    // MARK: Approvals

    func approval(id: String, method: String, params: JSONValue) -> (ApprovalRequest, RequestKind)? {
        let itemID = params["itemId"]?.string
        let reason = params["reason"]?.string.map { "Codex says: \($0)" }
        let agentLabel = isChild(params) ? agentName(of: params["threadId"]?.string) : nil

        switch method {
        case "item/commandExecution/requestApproval":
            let command = params["command"]?.string.map(Self.displayCommand) ?? itemID.flatMap { commands[$0] } ?? ""
            let escalated = turnMode == .plan || turnMode == .auto
            var notes = [
                escalated
                    ? "Allow gives this command full access to your Mac, not only this project."
                    : "Runs in the project sandbox. If the sandbox blocks it, Codex may retry it outside without asking again."
            ]
            if Self.opensInteractiveSession(command) {
                notes.append("This opens an interactive session. Anything run inside it won't ask again.")
            }
            if let host = params["networkApprovalContext"]?["host"]?.string {
                notes.append("Needs network access to \(host).")
            }
            let request = ApprovalRequest(
                id: id, toolCallID: itemID, toolKind: .shell,
                title: escalated ? "Run outside the sandbox?" : "Run this command?", detail: command, reason: reason,
                input: params,
                rememberOptions: [
                    RememberOption(id: "session", label: "Allow this command for the session", payload: "acceptForSession")
                ],
                notes: notes, workingDirectory: foreignDirectory(params["cwd"]?.string), agentLabel: agentLabel)
            return (request, .command)

        case "item/fileChange/requestApproval":
            let diffs = itemID.flatMap { fileDiffs[$0] } ?? []
            let notes = params["grantRoot"]?.string.map { ["Allow also lets Codex write anywhere in \($0) for this session."] }
            let request = ApprovalRequest(
                id: id, toolCallID: itemID, toolKind: .edit, title: "Apply this edit?",
                detail: diffs.map(Self.displayPath).joined(separator: ", "), reason: reason, diff: diffs, input: params,
                rememberOptions: [
                    RememberOption(id: "session", label: "Allow these files for the session", payload: "acceptForSession")
                ],
                notes: notes ?? [], agentLabel: agentLabel)
            return (request, .fileChange)

        case "item/tool/requestUserInput":
            let questions = (params["questions"]?.array ?? []).map { question in
                AgentQuestion(
                    id: question["id"]?.string ?? "", header: question["header"]?.string ?? "Question",
                    question: question["question"]?.string ?? "",
                    options: (question["options"]?.array ?? []).map {
                        AgentQuestion.Option(label: $0["label"]?.string ?? "", detail: $0["description"]?.string ?? "")
                    })
            }
            let request = ApprovalRequest(
                id: id, kind: .questions(questions), toolCallID: itemID, toolKind: .question,
                title: "Codex has a question", input: params, agentLabel: agentLabel)
            return (request, .userInput)

        case "mcpServer/elicitation/request":
            return elicitation(id: id, params: params, agentLabel: agentLabel)

        default:
            return nil
        }
    }

    private func elicitation(
        id: String, params: JSONValue, agentLabel: String?
    ) -> (ApprovalRequest, RequestKind)? {
        let server = params["serverName"]?.string ?? "An MCP server"
        let message = params["message"]?.string ?? "\(server) is asking for approval."
        let meta = params["_meta"]

        if meta?["codex_approval_kind"]?.string == "mcp_tool_call" {
            let arguments = (meta?["tool_params_display"]?.array ?? []).map { parameter -> String in
                let name = parameter["display_name"]?.string ?? parameter["name"]?.string ?? "value"
                return "\(name): \(Self.describe(parameter["value"]))"
            }
            let canRemember = meta?["persist"]?.array?.contains(.string("session")) == true
            let request = ApprovalRequest(
                id: id, toolKind: .mcp, title: message, detail: arguments.joined(separator: "\n"), input: params,
                rememberOptions: canRemember
                    ? [RememberOption(id: "session", label: "Allow this tool for the session", payload: "session")] : [],
                agentLabel: agentLabel)
            return (request, .mcpApproval)
        }

        switch params["mode"]?.string {
        case "url":
            guard let url = params["url"]?.string.flatMap(URL.init(string:)), ["http", "https"].contains(url.scheme ?? "")
            else { return nil }
            let request = ApprovalRequest(
                id: id, toolKind: .mcp, title: "\(server) wants you to open a page", detail: message, input: params,
                agentLabel: agentLabel, link: url)
            return (request, .link)
        case "form":
            let questions = Self.questions(fromSchema: params["requestedSchema"])
            let request = ApprovalRequest(
                id: id, kind: questions.isEmpty ? .tool : .questions(questions), toolKind: .mcp,
                title: "\(server) is asking", detail: message, input: params, agentLabel: agentLabel)
            return (request, .form)
        default:
            return nil
        }
    }

    /// Maps an MCP form onto the question UI. Everything else about the schema is left to the server.
    static func questions(fromSchema schema: JSONValue?) -> [AgentQuestion] {
        guard let properties = schema?["properties"]?.object else { return [] }
        let required = (schema?["required"]?.array ?? []).compactMap(\.string)
        let names = required + properties.keys.filter { !required.contains($0) }.sorted()
        return names.compactMap { name in
            guard let field = properties[name] else { return nil }
            let title = field["title"]?.string ?? name
            let values = field["enum"]?.array?.compactMap(\.string) ?? field["items"]?["enum"]?.array?.compactMap(\.string) ?? []
            var options = values.map { AgentQuestion.Option(label: $0) }
            if field["type"]?.string == "boolean" {
                options = [AgentQuestion.Option(label: "Yes"), AgentQuestion.Option(label: "No")]
            }
            return AgentQuestion(
                id: name, header: title, question: field["description"]?.string ?? title, options: options,
                allowsMultiple: field["type"]?.string == "array", isOptional: !required.contains(name))
        }
    }

    /// Turns chosen answers back into the types an MCP form's schema asked for.
    static func formContent(answers: [String: [String]], schema: JSONValue?) -> JSONValue {
        var content: [String: JSONValue] = [:]
        for (name, values) in answers {
            guard let first = values.first else { continue }
            let field = schema?["properties"]?[name]
            switch field?["type"]?.string {
            case "boolean": content[name] = .bool(first == "Yes")
            case "integer": content[name] = Int64(first).map(JSONValue.int) ?? .string(first)
            case "number": content[name] = Double(first).map(JSONValue.double) ?? .string(first)
            case "array": content[name] = .array(values.map(JSONValue.string))
            default: content[name] = .string(first)
            }
        }
        return .object(content)
    }

    private func agentName(of thread: String?) -> String {
        thread.flatMap { agentNames[$0] }.map { "Sub-agent: \($0)" } ?? "Sub-agent"
    }

    private func foreignDirectory(_ path: String?) -> String? {
        guard let path, FilePath.resolved(path) != FilePath.resolved(workingDirectory) else { return nil }
        return path
    }

    /// Whether every path in a change is ordinary project content, for auto-accepting edits.
    func changesStayInProject(_ itemID: String) -> Bool {
        guard let paths = filePaths[itemID], !paths.isEmpty else { return false }
        return paths.allSatisfy { CodexMode.isOrdinaryProjectFile($0, root: workingDirectory) }
    }

    // MARK: Helpers

    private static func describe(_ value: JSONValue?) -> String {
        guard let value else { return "" }
        if let string = value.string { return string }
        return (try? value.serialized()).map { String(decoding: $0, as: UTF8.self) } ?? ""
    }

    private static func status(_ item: JSONValue) -> ToolStatus {
        switch item["status"]?.string {
        case "completed": .succeeded
        case "failed": .failed
        case "declined": .denied
        case "inProgress": .running
        default: .succeeded
        }
    }

    private static func todoItem(_ value: JSONValue) -> TodoItem? {
        guard let step = value["step"]?.string else { return nil }
        let status: TodoItem.Status =
            switch value["status"]?.string {
            case "completed": .completed
            case "inProgress": .inProgress
            default: .pending
            }
        return TodoItem(text: step, status: status)
    }

    /// A trailing "Moved to: …" comes with the diff of a moved file, and isn't part of its content.
    private static func diffs(_ changes: [JSONValue], workingDirectory: String) -> [DiffFile] {
        changes.flatMap { change -> [DiffFile] in
            let path = ToolDescriber.relative(change["path"]?.string ?? "", to: workingDirectory)
            var body = change["diff"]?.string ?? ""
            let movePath = change["kind"]?["move_path"]?.string
            if let movePath, let range = body.range(of: "\n\nMoved to: \(movePath)", options: [.backwards, .anchored]) {
                body.removeSubrange(range)
            }
            let movedTo = movePath.map { ToolDescriber.relative($0, to: workingDirectory) }
            switch change["kind"]?["type"]?.string {
            case "add":
                return [DiffFile(path: path, newContent: body)]
            case "delete":
                return [DiffFile(path: path, removedContent: body)]
            default:
                let parsed = DiffParser.parse(body, defaultPath: path)
                return parsed.isEmpty
                    ? [DiffFile(path: path, movedTo: movedTo)]
                    : parsed.map { DiffFile(path: path, movedTo: movedTo, lines: $0.lines) }
            }
        }
    }

    /// Codex wraps commands as `/bin/zsh -lc …`, quoting them with shlex. That means quotes can be
    /// absent or split across several chunks, so the original can only be recovered by splitting
    /// shell words. This text goes on approval cards, so it has to be exactly what will run.
    static func displayCommand(_ command: String) -> String {
        guard let words = shellWords(command), words.count == 3, words[1] == "-lc" || words[1] == "-c",
            ["sh", "bash", "zsh"].contains((words[0] as NSString).lastPathComponent)
        else { return command }
        return words[2]
    }

    /// Splits text into POSIX shell words, or returns nil if the quoting doesn't balance.
    static func shellWords(_ text: String) -> [String]? {
        var words: [String] = []
        var word = String.UnicodeScalarView()
        var inWord = false
        var quote: Unicode.Scalar?
        var scalars = text.unicodeScalars.makeIterator()
        while let scalar = scalars.next() {
            if quote == "'" {
                if scalar == "'" { quote = nil } else { word.append(scalar) }
            } else if quote == "\"" {
                if scalar == "\"" {
                    quote = nil
                } else if scalar == "\\" {
                    guard let next = scalars.next() else { return nil }
                    if next == "\n" { continue }
                    if !["\"", "\\", "$", "`"].contains(next) { word.append(scalar) }
                    word.append(next)
                } else {
                    word.append(scalar)
                }
            } else if scalar == "'" || scalar == "\"" {
                quote = scalar
                inWord = true
            } else if scalar == "\\" {
                guard let next = scalars.next() else { return nil }
                word.append(next)
                inWord = true
            } else if scalar == " " || scalar == "\t" || scalar == "\n" {
                if inWord { words.append(String(word)) }
                word = String.UnicodeScalarView()
                inWord = false
            } else {
                word.append(scalar)
                inWord = true
            }
        }
        guard quote == nil else { return nil }
        if inWord { words.append(String(word)) }
        return words
    }

    private static func opensInteractiveSession(_ command: String) -> Bool {
        let interactive: Set<String> = ["sh", "bash", "zsh", "fish", "python", "python3", "node", "ruby", "irb", "perl"]
        guard let words = shellWords(command), words.count == 1 else { return false }
        return interactive.contains((words[0] as NSString).lastPathComponent)
    }

    static func rateLimit(_ value: JSONValue) -> RateLimitSnapshot? {
        var windows: [RateLimitWindow] = []
        for (key, fallback) in [("primary", "Short limit"), ("secondary", "Weekly limit")] {
            guard let window = value[key], let used = window["usedPercent"]?.double else { continue }
            let minutes = window["windowDurationMins"]?.int
            windows.append(
                RateLimitWindow(
                    id: key, label: minutes.map(windowLabel) ?? fallback, utilization: used / 100,
                    resetsAt: window["resetsAt"]?.double.map(Date.init(timeIntervalSince1970:))))
        }
        guard !windows.isEmpty else { return nil }
        return RateLimitSnapshot(agent: .codex, windows: windows, isExhausted: !(value["rateLimitReachedType"]?.isNull ?? true))
    }

    private static func windowLabel(minutes: Int) -> String {
        if minutes >= 10_080 { return "Weekly limit" }
        if minutes >= 60 { return "\(minutes / 60)-hour limit" }
        return "\(minutes)-minute limit"
    }
}

/// Codex's controls for each `ApprovalMode`, chosen from measured behaviour. `on-request` only asks
/// when a command needs to leave the sandbox, so asking about every command needs `untrusted`.
enum CodexMode {
    /// Anything that runs here was either approved by the user or stays inside the sandbox.
    static func approvalPolicy(_ mode: ApprovalMode) -> JSONValue {
        switch mode {
        case .ask, .acceptEdits: "untrusted"
        case .plan, .auto: "on-request"
        case .bypass: "never"
        }
    }

    /// The user's own sandbox settings, which Marika must not silently weaken or override.
    struct SandboxSettings: Sendable, Equatable {
        var networkAccess = false
        var excludeTmpdirEnvVar = false
        var excludeSlashTmp = false
    }

    static func sandboxPolicy(_ mode: ApprovalMode, workingDirectory: String, settings: SandboxSettings, additionalDirectories: [String] = []) -> JSONValue {
        switch mode {
        case .plan:
            return ["type": "readOnly", "networkAccess": false]
        case .bypass:
            return ["type": "dangerFullAccess"]
        case .ask, .acceptEdits, .auto:
            // Every command in the asking modes is approved first, so allowing the network adds no
            // unreviewed access. Without it, an approved `npm install` just fails like a DNS fault.
            let network = mode == .auto ? settings.networkAccess : true
            return [
                "type": "workspaceWrite", "writableRoots": .array(([workingDirectory] + additionalDirectories).map(JSONValue.string)), "networkAccess": .bool(network),
                "excludeTmpdirEnvVar": .bool(settings.excludeTmpdirEnvVar), "excludeSlashTmp": .bool(settings.excludeSlashTmp),
            ]
        }
    }

    /// True for a file inside the project that isn't version control or agent configuration.
    static func isOrdinaryProjectFile(_ path: String, root: String) -> Bool {
        let resolvedRoot = FilePath.resolved(root)
        var existing = URL(fileURLWithPath: path, relativeTo: URL(fileURLWithPath: root, isDirectory: true)).standardizedFileURL
        var missing: [String] = []
        while !FileManager.default.fileExists(atPath: existing.path), existing.path != "/" {
            missing.insert(existing.lastPathComponent, at: 0)
            existing.deleteLastPathComponent()
        }
        let resolved = ([FilePath.resolved(existing.path)] + missing).joined(separator: "/")
        guard resolved.hasPrefix(resolvedRoot + "/") else { return false }
        let protected: Set<String> = [".git", ".codex", ".agents"]
        return !resolved.dropFirst(resolvedRoot.count + 1).split(separator: "/").contains { protected.contains(String($0)) }
    }
}
